#!/usr/bin/env node
'use strict';
// Source-only oracle: real published CLIParser/YargsAdapter + CheckoutCmd/RevertCmd.
// Each parse gets a fresh process because the published parser uses singleton yargs.
// The actual report stops at an injected checkout service, never materializing files.
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createRequire } = require('node:module');
const { spawnSync } = require('node:child_process');
const packageRoot = process.argv[2] || '/var/home/zoltan/.bvm/versions/2.2.94/bit-2.2.94/node_modules/@teambit/bit';
const input = process.argv.slice(3);
const marker = 'CHECKOUT_POSITIONAL_RESULT=';
function describe(value) {
  if (typeof value === 'number' && !Number.isFinite(value)) return { type: 'number', nonFinite: String(value) };
  return { type: typeof value, value, negativeZero: typeof value === 'number' && Object.is(value, -0) };
}
async function one(spec) {
  process.argv = [process.execPath, path.join(packageRoot, 'bin/bit'), ...spec.argv];
  const req = createRequire(path.join(packageRoot, 'package.json'));
  const { CLIParser } = req('@teambit/cli/dist/cli-parser.js');
  const { CheckoutCmd } = req('@teambit/checkout/dist/checkout-cmd.js');
  const { RevertCmd } = req('@teambit/checkout/dist/revert-cmd.js');
  const boundary = new Error('oracle checkout service boundary');
  let call;
  const checkout = { checkoutByCLIValues: async (pattern, props) => {
    call = { pattern: describe(pattern), props };
    throw boundary;
  } };
  const commands = [new CheckoutCmd(checkout), new RevertCmd(checkout)];
  const parser = new CLIParser(commands, {}, { values: () => [] });
  const result = { label: spec.label, argv: spec.argv };
  try {
    const runner = await parser.parse(spec.argv);
    result.parsedArgs = runner.args.map(describe);
    result.parsedFlags = runner.flags;
    try {
      // Execute the real report's validations and String(to), not CommandRunner
      // history/analytics/startup, and stop before calling any VCS implementation.
      await runner.command.report(runner.args, runner.flags);
    } catch (error) {
      if (error !== boundary) result.reportError = { name: error.name, message: error.message };
    }
    if (call) result.checkoutService = call;
  } catch (error) {
    result.parseError = { name: error.name, message: error.message };
  }
  process.stdout.write(marker + JSON.stringify(result) + '\n');
}
if (input[0] === '--one') {
  one(JSON.parse(input[1])).catch(error => { console.error(error.stack); process.exitCode = 1; });
} else {
  const targets = [
    '38938e0', '38938e+0', '123e-2', '0e1', '0123', '0000001', '1234567',
    '0.001', '0xabc', '0XABC', '0x20000000000001', '9007199254740992',
    '9007199254740991', '1e21', '1e-7', '1E3', '123.', '.123', '+123',
    '-123', '-0', 'NaN', 'Infinity', '-Infinity', 'head', 'head~2', 'latest',
    'reset', 'main', '0.0.1', '1.2.3-beta.1', 'deadbee', 'scope/name',
  ];
  const specs = targets.flatMap(target => [
    { label: `checkout:${target}`, argv: ['checkout', target, 'bar/foo', '-x'] },
    { label: `revert:${target}`, argv: ['revert', 'bar/foo', target, '-x'] },
  ]);
  for (const pattern of ['1234567', '0123', '38938e0', 'scope/name', 'name/space', 'bar/foo@0.0.1']) {
    specs.push({ label: `checkout-pattern:${pattern}`, argv: ['checkout', 'head', pattern, '-x'] });
    specs.push({ label: `revert-pattern:${pattern}`, argv: ['revert', pattern, 'main', '-x'] });
  }
  const selected = input[0] === '--labels' ? new Set(JSON.parse(input[1])) : null;
  const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'checkout-positional-oracle-'));
  const records = [];
  for (const spec of specs.filter(spec => !selected || selected.has(spec.label))) {
    const result = spawnSync(process.execPath, [__filename, packageRoot, '--one', JSON.stringify(spec)], {
      cwd: temp,
      env: { ...process.env, HOME: temp, USERPROFILE: temp, BIT_GLOBALS_DIR: path.join(temp, 'bit'),
        BVM_GLOBALS_DIR: path.join(temp, 'bvm'), FORCE_COLOR: '0', CI: '', BIT_NATIVE: 'off' },
      encoding: 'utf8', timeout: 60000, maxBuffer: 4 * 1024 * 1024,
    });
    const position = result.stdout?.lastIndexOf(marker) ?? -1;
    records.push({ label: spec.label, argv: spec.argv, status: result.status,
      result: position < 0 ? null : JSON.parse(result.stdout.slice(position + marker.length).trim()),
      stdoutBeforeResult: position < 0 ? result.stdout : result.stdout.slice(0, position),
      stderr: result.stderr, spawnError: result.error?.message });
  }
  console.log(JSON.stringify({ node: process.version,
    bitVersion: JSON.parse(fs.readFileSync(path.join(packageRoot, 'package.json'))).version,
    packageRoot, disposableDirectory: temp, records }, null, 2));
}
